// Generated by Codex and not thoroughly checked for correctness.
func TestSparseMoves(t *testing.T) {
	a, b, c := "A", "B", "C"
	base := []items.OrderedItem{{ProblemID: a, Position: items.PositionGap}, {ProblemID: b, Position: 2 * items.PositionGap}, {ProblemID: c, Position: 3 * items.PositionGap}}
	for _, tc := range []struct {
		name  string
		moves []items.Move
		want  []string
		err   error
	}{
		{"before", []items.Move{{ProblemID: c, Before: &a}}, []string{c, a, b}, nil},
		{"after", []items.Move{{ProblemID: a, After: &b}}, []string{b, a, c}, nil},
		{"append", []items.Move{{ProblemID: a}}, []string{b, c, a}, nil},
		{"no change", []items.Move{{ProblemID: a, Before: &b}}, []string{a, b, c}, nil},
		{"sequential batch", []items.Move{{ProblemID: c, Before: &a}, {ProblemID: b, Before: &a}}, []string{c, b, a}, nil},
		{"invalid later move", []items.Move{{ProblemID: c, Before: &a}, {ProblemID: "missing"}}, nil, items.ErrOrderConflict},
		{"missing anchor", []items.Move{{ProblemID: a, Before: pointer("missing")}}, nil, items.ErrOrderConflict},
		{"self", []items.Move{{ProblemID: a, Before: &a}}, nil, items.ErrInvalidOperation},
		{"two anchors", []items.Move{{ProblemID: a, Before: &b, After: &c}}, nil, items.ErrInvalidOperation},
		{"blank anchor", []items.Move{{ProblemID: a, Before: pointer(" ")}}, nil, items.ErrInvalidOperation},
		{"blank item", []items.Move{{ProblemID: " "}}, nil, items.ErrInvalidOperation},
		{"empty", nil, nil, items.ErrInvalidOperation},
	} {
		t.Run(tc.name, func(t *testing.T) {
			original := append([]items.OrderedItem{}, base...)
			got, rebalanced, err := items.ApplyMoves(base, tc.moves)
			if !errors.Is(err, tc.err) {
				t.Fatalf("error=%v want %v", err, tc.err)
			}
			if !reflect.DeepEqual(base, original) {
				t.Fatal("mutated input")
			}
			if err != nil {
				return
			}
			if rebalanced {
				t.Fatal("unexpected rebalance")
			}
			for index, item := range got {
				if item.ProblemID != tc.want[index] || item.Position <= 0 || index > 0 && item.Position <= got[index-1].Position {
					t.Fatalf("bad order %+v", got)
				}
			}
		})
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestSparseMovesRebalanceEarly(t *testing.T) {
	a := "A"
	for _, order := range [][]items.OrderedItem{
		{{ProblemID: "A", Position: 1000}, {ProblemID: "B", Position: 2000}, {ProblemID: "C", Position: 3000}},
		{{ProblemID: "A", Position: items.MaxPosition - 300}, {ProblemID: "B", Position: items.MaxPosition - 200}, {ProblemID: "C", Position: items.MaxPosition - 100}},
	} {
		moves := []items.Move{{ProblemID: "C", Before: &a}}
		if order[0].Position > items.PositionGap {
			moves = []items.Move{{ProblemID: "A"}}
		}
		got, rebalanced, err := items.ApplyMoves(order, moves)
		if err != nil || !rebalanced {
			t.Fatalf("rebalanced=%v error=%v", rebalanced, err)
		}
		for index, item := range got {
			if item.Position != int64(index+1)*items.PositionGap {
				t.Fatalf("bad positions %+v", got)
			}
		}
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestBulkValidationBeforeDatabaseAccess(t *testing.T) {
	repository := items.NewRepository(nil, 0)
	for _, input := range [][]items.ListItem{nil, {{ProblemId: " "}}, {{ProblemId: "A"}, {ProblemId: " A "}}} {
		if _, err := repository.BulkAdd(t.Context(), 1, 1, input); !errors.Is(err, items.ErrInvalidOperation) {
			t.Fatal(err)
		}
	}
	for _, ids := range [][]string{nil, {" "}, {"A", " A "}} {
		if _, err := repository.BulkRemove(t.Context(), 1, 1, ids); !errors.Is(err, items.ErrInvalidOperation) {
			t.Fatal(err)
		}
	}
}

func pointer(value string) *string { return &value }
